 // src/services/footballApi.js
import axios from 'axios'

// ============================================
// FOOTBALL-DATA.ORG API (For crests/logos)
// ============================================
const FOOTBALL_DATA_KEY = '5ac44b9e7ae64f30891be70bacd04900'
const FOOTBALL_DATA_URL = 'https://api.football-data.org/v4'

// ============================================
// THESPORTSDB API (For PSL)
// ============================================
const THESPORTSDB_URL = 'https://www.thesportsdb.com/api/v1/json/3'

// ============================================
// COMPETITIONS
// ============================================
export const COMPETITIONS = {
    PREMIER_LEAGUE: 'PL',
    LA_LIGA: 'PD',
    BUNDESLIGA: 'BL1',
    SERIE_A: 'SA',
    LIGUE_1: 'FL1',
    CHAMPIONS_LEAGUE: 'CL',
    PSL: 'PSL',
}

const footballDataClient = axios.create({
    baseURL: FOOTBALL_DATA_URL,
    headers: {
        'X-Auth-Token': FOOTBALL_DATA_KEY
    }
})

// ============================================
// GET MATCHES FROM FOOTBALL-DATA.ORG
// ============================================
export async function getTodaysMatches(competition = 'PL') {
    try {
        // If PSL, use TheSportsDB
        if (competition === 'PSL') {
            return await getPSLMatches()
        }

        const today = new Date()
        const future = new Date()
        future.setDate(today.getDate() + 30)

        const response = await footballDataClient.get(`/competitions/${competition}/matches`, {
            params: {
                dateFrom: today.toISOString().split('T')[0],
                dateTo: future.toISOString().split('T')[0]
            }
        })

        if (response.data.matches && response.data.matches.length > 0) {
            return response.data.matches
        }

        return getSampleMatches()

    } catch (error) {
        console.error('Error fetching matches:', error)
        return getSampleMatches()
    }
}

// ============================================
// GET PSL MATCHES FROM THESPORTSDB
// ============================================
export async function getPSLMatches() {
    try {
        const today = new Date().toISOString().split('T')[0]
        const response = await axios.get(`${THESPORTSDB_URL}/eventsday.php`, {
            params: { d: today }
        })

        // Filter for South African leagues
        const pslEvents = response.data.events?.filter(event => 
            event.strLeague?.includes('South Africa') || 
            event.strLeague?.includes('PSL') ||
            event.strLeague?.includes('Premier Soccer League')
        ) || []

        if (pslEvents.length > 0) {
            return pslEvents
        }

        return getSamplePSLMatches()

    } catch (error) {
        console.error('PSL matches error:', error)
        return getSamplePSLMatches()
    }
}

// ============================================
// FORMAT MATCH FOR DISPLAY (WITH CRESTS)
// ============================================
export function formatMatch(match) {
    // Check if it's a TheSportsDB match (PSL)
    if (match.strHomeTeam) {
        return {
            id: match.idEvent || `psl-${Math.random()}`,
            matchId: match.idEvent || `psl-${Math.random()}`,
            homeTeam: {
                name: match.strHomeTeam || 'Unknown',
                crest: match.strHomeTeamBadge || null,
                badge: getTeamEmoji(match.strHomeTeam)
            },
            awayTeam: {
                name: match.strAwayTeam || 'Unknown',
                crest: match.strAwayTeamBadge || null,
                badge: getTeamEmoji(match.strAwayTeam)
            },
            league: match.strLeague || 'PSL (South Africa)',
            leagueId: 'psl',
            kickoff: match.dateEvent || new Date().toISOString(),
            status: match.strStatus === 'FT' ? 'finished' : 'upcoming',
            score: {
                home: parseInt(match.intHomeScore) || 0,
                away: parseInt(match.intAwayScore) || 0
            },
            venue: match.strVenue || 'Unknown Venue',
            aiPrediction: generateAIPrediction(match)
        }
    }

    // Football-Data.org match (has crests)
    const homeTeam = match.homeTeam || {}
    const awayTeam = match.awayTeam || {}
    const competition = match.competition || {}

    let status = 'upcoming'
    const matchStatus = match.status || ''
    if (matchStatus === 'FINISHED' || matchStatus === 'FT') {
        status = 'finished'
    } else if (matchStatus === 'LIVE' || matchStatus === 'IN_PLAY') {
        status = 'live'
    }

    let homeScore = 0
    let awayScore = 0
    if (match.score?.fullTime?.home !== null && match.score?.fullTime?.home !== undefined) {
        homeScore = match.score.fullTime.home
        awayScore = match.score.fullTime.away
    } else if (match.score?.halfTime?.home !== null && match.score?.halfTime?.home !== undefined) {
        homeScore = match.score.halfTime.home
        awayScore = match.score.halfTime.away
    }

    return {
        id: match.id || `match-${Math.random()}`,
        matchId: match.id || `match-${Math.random()}`,
        homeTeam: {
            name: homeTeam.name || 'Unknown',
            crest: homeTeam.crest || null,
            badge: getTeamEmoji(homeTeam.name)
        },
        awayTeam: {
            name: awayTeam.name || 'Unknown',
            crest: awayTeam.crest || null,
            badge: getTeamEmoji(awayTeam.name)
        },
        league: competition.name || 'Unknown League',
        leagueId: competition.code || 'unknown',
        kickoff: match.utcDate || new Date().toISOString(),
        status: status,
        score: {
            home: homeScore || 0,
            away: awayScore || 0
        },
        venue: match.venue || 'Unknown Venue',
        aiPrediction: generateAIPrediction(match)
    }
}

// ============================================
// GENERATE AI PREDICTION
// ============================================
function generateAIPrediction(match) {
    const homeScore = match.score?.home || match.score?.fullTime?.home || match.intHomeScore || 0
    const awayScore = match.score?.away || match.score?.fullTime?.away || match.intAwayScore || 0
    
    if (match.status === 'finished' || match.status === 'FINISHED' || match.status === 'FT' || match.strStatus === 'FT') {
        return {
            result: {
                home: homeScore > awayScore ? 90 : 20,
                draw: homeScore === awayScore ? 80 : 15,
                away: awayScore > homeScore ? 90 : 20
            },
            confidence: 95,
            isFinished: true,
            actualScore: `${homeScore}-${awayScore}`
        }
    }
    
    const homeStrength = Math.random() * 0.4 + 0.3
    const awayStrength = Math.random() * 0.4 + 0.3
    
    let homeWin = Math.round((homeStrength / (homeStrength + awayStrength)) * 70 + 10)
    let awayWin = Math.round((awayStrength / (homeStrength + awayStrength)) * 70 + 10)
    let draw = 100 - homeWin - awayWin
    
    homeWin = Math.max(10, Math.min(80, homeWin))
    awayWin = Math.max(10, Math.min(80, awayWin))
    draw = Math.max(5, Math.min(40, draw))
    
    const total = homeWin + draw + awayWin
    if (total !== 100) {
        const diff = 100 - total
        homeWin += Math.round(diff / 2)
        awayWin += diff - Math.round(diff / 2)
    }
    
    return {
        result: {
            home: Math.max(10, Math.min(80, homeWin)),
            draw: Math.max(5, Math.min(40, draw)),
            away: Math.max(10, Math.min(80, awayWin))
        },
        yellowCards: {
            home: Math.floor(Math.random() * 3) + 1,
            away: Math.floor(Math.random() * 3) + 1
        },
        redCards: {
            home: Math.random() > 0.85 ? 1 : 0,
            away: Math.random() > 0.9 ? 1 : 0
        },
        corners: {
            home: Math.floor(Math.random() * 5) + 3,
            away: Math.floor(Math.random() * 5) + 3
        },
        confidence: Math.floor(Math.random() * 25) + 55
    }
}

// ============================================
// SAMPLE MATCHES (WITH CRESTS)
// ============================================
function getSampleMatches() {
    const now = new Date()
    return [
